11	// ============================================================
12	// Nonzero 算子 Host 端实现
13	// 两阶段设计:
14	//   Pass 1 (nonzero_count): 各核统计非零元素数量
15	//   Pass 2 (nonzero_output): 各核输出 flatIdx
16	//   Host 端将 flatIdx 转换为多维坐标
17	// ============================================================
18	
19	#include "torch_kernel_helper.h"
20	#include "tiling/platform/platform_ascendc.h"
21	#include "aclrtlaunch_nonzero_count.h"
22	#include "aclrtlaunch_nonzero_output.h"
23	
24	#include <torch/extension.h>
25	#include <vector>
26	
27	namespace ascend_kernel {
28	
29	constexpr int64_t CACHE_LINE_BYTES = 512;
30	constexpr int64_t UB_ALIGN_BYTES = 32;
31	constexpr int64_t MAX_NDIM = 8;
32	
33	static std::vector<at::Tensor> nonzero_impl(
34	    const at::Tensor &x,
35	    int64_t as_tuple)
36	{
37	    // ---- 输入校验 ----
38	    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1,
39	                "nonzero: input must be on NPU device");
40	    TORCH_CHECK(x.is_contiguous(),
41	                "nonzero: input must be contiguous");
42	    TORCH_CHECK(x.scalar_type() == at::kFloat ||
43	                x.scalar_type() == at::kHalf ||
44	                x.scalar_type() == at::kBFloat16 ||
45	                x.scalar_type() == at::kInt ||
46	                x.scalar_type() == at::kLong,
47	                "nonzero: unsupported dtype");
48	
49	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
50	    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
51	    uint64_t ubSize;
52	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
53	
54	    int64_t totalElements = x.numel();
55	    int64_t ndim = x.dim();
56	    int64_t dtypeSize = x.element_size();
57	
58	    if (totalElements == 0) {
59	        auto emptyOut = at::empty({0, ndim},
60	                                   at::TensorOptions().dtype(at::kLong).device(x.device()));
61	        if (as_tuple) {
62	            std::vector<at::Tensor> parts;
63	            for (int64_t d = 0; d < ndim; d++) {
64	                parts.push_back(at::empty({0},
65	                    at::TensorOptions().dtype(at::kLong).device(x.device())));
66	            }
67	            return parts;
68	        }
69	        return {emptyOut};
70	    }
71	
72	    // ---- Block 级 Tiling ----
73	    int64_t alignElementsCore = std::max(int64_t(1), CACHE_LINE_BYTES / dtypeSize);
74	    int64_t totalLengthCore = (totalElements + coreNum - 1) / coreNum;
75	    int64_t totalLengthCoreAlign =
76	        ((totalLengthCore + alignElementsCore - 1) / alignElementsCore) * alignElementsCore;
77	    int64_t usedCoreNum = (totalElements + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
78	    if (usedCoreNum < 1) usedCoreNum = 1;
79	    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
80	
81	    int64_t formerNum = std::max(int64_t(0), usedCoreNum - 1);
82	    int64_t formerLength = totalLengthCoreAlign;
83	    int64_t tailLength = std::max(int64_t(0), totalElements - formerNum * formerLength);
84	
85	    // ---- UB 级 tileLength ----
86	    constexpr int64_t extraBufBytes = 256;
87	    int64_t bufferCoefficient = dtypeSize * 2;
88	    int64_t availableUB = static_cast<int64_t>(ubSize) - extraBufBytes;
89	    if (availableUB < bufferCoefficient) availableUB = bufferCoefficient;
90	    int64_t maxTileElements = availableUB / bufferCoefficient;
91	    int64_t alignElementsUb = std::max(int64_t(1), UB_ALIGN_BYTES / dtypeSize);
92	    int64_t tileLength = (maxTileElements / alignElementsUb) * alignElementsUb;
93	    if (tileLength < alignElementsUb) tileLength = alignElementsUb;
94	
95	    // ---- workspace ----
96	    auto workspaceOpts = at::TensorOptions().dtype(at::kLong).device(x.device());
97	    auto workspace = at::zeros({coreNum * 2}, workspaceOpts);
98	
99	    // ---- Pass 1: Count ----
100	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
101	    int64_t totalElementsVal = totalElements;
102	    int64_t formerNumVal = formerNum;
103	    int64_t formerLengthVal = formerLength;
104	    int64_t tailLengthVal = tailLength;
105	    int64_t tileLengthVal = tileLength;
106	
107	    EXEC_KERNEL_CMD(nonzero_count, blockDim,
108	                    x, workspace, totalElementsVal, formerNumVal,
109	                    formerLengthVal, tailLengthVal, tileLengthVal, dtypeSize);
110	
111	    // ---- 读取 per-core counts ----
112	    auto cpuWs = workspace.to(at::kCPU);
113	    const int64_t *wsData = cpuWs.data_ptr<int64_t>();
114	
115	    std::vector<int64_t> perCoreOffsets(usedCoreNum + 1, 0);
116	    int64_t totalNonzero = 0;
117	    for (int64_t c = 0; c < usedCoreNum; c++) {
118	        perCoreOffsets[c] = totalNonzero;
119	        totalNonzero += wsData[c];
120	    }
121	    perCoreOffsets[usedCoreNum] = totalNonzero;
122	
123	    if (totalNonzero == 0) {
124	        auto emptyOut = at::empty({0, ndim},
125	                                   at::TensorOptions().dtype(at::kLong).device(x.device()));
126	        if (as_tuple) {
127	            std::vector<at::Tensor> parts;
128	            for (int64_t d = 0; d < ndim; d++) {
129	                parts.push_back(at::empty({0},
130	                    at::TensorOptions().dtype(at::kLong).device(x.device())));
131	            }
132	            return parts;
133	        }
134	        return {emptyOut};
135	    }
136	
137	    // ---- 写入 per-core offsets ----
138	    auto offsetTensor = at::empty({usedCoreNum},
139	                                   at::TensorOptions().dtype(at::kLong).device(x.device()));
140	    auto offsetCpu = at::empty({usedCoreNum}, at::TensorOptions().dtype(at::kLong));
141	    int64_t *offsetsData = offsetCpu.data_ptr<int64_t>();
142	    for (int64_t c = 0; c < usedCoreNum; c++) {
143	        offsetsData[c] = perCoreOffsets[c];
144	    }
145	    offsetTensor.copy_(offsetCpu.to(x.device()));
146	
147	    // ---- kernel 输出: 1D flatIdx tensor ----
148	    auto flatIdxTensor = at::empty({totalNonzero},
149	                                    at::TensorOptions().dtype(at::kLong).device(x.device()));
150	    int64_t ndimVal = ndim;
151	
152	    // ---- Pass 2: Output flatIdx ----
153	    EXEC_KERNEL_CMD(nonzero_output, blockDim,
154	                    x, flatIdxTensor, offsetTensor,
155	                    totalElementsVal, ndimVal,
156	                    formerNumVal, formerLengthVal, tailLengthVal,
157	                    tileLengthVal, dtypeSize);
158	
159	    // ---- Host 端: flatIdx → 多维坐标 ----
160	    auto flatIdxCpu = flatIdxTensor.to(at::kCPU);
161	    const int64_t *flatData = flatIdxCpu.data_ptr<int64_t>();
162	
163	    // 计算 C-order strides
164	    int64_t strides[MAX_NDIM] = {0};
165	    if (ndim > 0) {
166	        strides[ndim - 1] = 1;
167	        for (int64_t d = ndim - 2; d >= 0; d--) {
168	            strides[d] = strides[d + 1] * x.size(d + 1);
169	        }
170	    }
171	
172	    auto outputCpu = at::empty({totalNonzero, ndim}, at::TensorOptions().dtype(at::kLong));
173	    int64_t *outputData = outputCpu.data_ptr<int64_t>();
174	    for (int64_t k = 0; k < totalNonzero; k++) {
175	        int64_t flatIdx = flatData[k];
176	        int64_t remaining = flatIdx;
177	        for (int64_t d = 0; d < ndim; d++) {
178	            int64_t stride = strides[d];
179	            int64_t coord;
180	            if (stride > 0) {
181	                coord = remaining / stride;
182	                remaining = remaining % stride;
183	            } else {
184	                coord = remaining;
185	                remaining = 0;
186	            }
187	            outputData[k * ndim + d] = coord;
188	        }
189	    }
190	
191	    auto output = outputCpu.to(x.device());
192	
193	    if (as_tuple) {
194	        std::vector<at::Tensor> parts;
195	        for (int64_t d = 0; d < ndim; d++) {
196	            parts.push_back(output.select(1, d).clone());
197	        }
198	        return parts;
199	    }
200	
201	    return {output};
202	}
203	
204	// =========================== 公开接口 ============================
205	
206	at::Tensor nonzero(const at::Tensor &x, int64_t as_tuple)
207	{
208	    auto result = nonzero_impl(x, as_tuple);
209	    return result[0];
210	}
211	
212	std::vector<at::Tensor> nonzero_as_tuple(const at::Tensor &x)
213	{
214	    return nonzero_impl(x, 1);
215	}
216	
217	}  // namespace ascend_kernel
