11	// ============================================================
12	// Nonzero 算子 Kernel 实现
13	// 两阶段设计:
14	//   Pass 1 (nonzero_count): 各核统计非零元素数量，写入 workspace
15	//   Pass 2 (nonzero_output): 各核输出非零元素的 flatIdx
16	//   Host 端将 flatIdx 转换为多维坐标
17	// ============================================================
18	
19	#include "kernel_operator.h"
20	
21	using namespace AscendC;
22	
23	constexpr int64_t BUFFER_NUM = 2;
24	constexpr int64_t MAX_NDIM = 8;
25	
26	
27	// =========================== 辅助: 零值检查 ============================
28	
29	template <typename T>
30	__aicore__ inline bool IsNonZero(T val)
31	{
32	    if constexpr (sizeof(T) == 2) {
33	        return (float)val != 0.0f;
34	    } else {
35	        return val != static_cast<T>(0);
36	    }
37	}
38	
39	
40	// =========================== Count Kernel ============================
41	
42	template <typename T>
43	class NonzeroCountKernel {
44	public:
45	    __aicore__ inline NonzeroCountKernel() {}
46	
47	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR countWs,
48	                                 int64_t totalElements, int64_t formerNum,
49	                                 int64_t formerLength, int64_t tailLength,
50	                                 int64_t tileLength, int64_t /*dtypeSize*/)
51	    {
52	        totalElements_ = totalElements;
53	        formerNum_ = formerNum;
54	        formerLength_ = formerLength;
55	        tailLength_ = tailLength;
56	        tileLength_ = tileLength;
57	
58	        inputGm_.SetGlobalBuffer((__gm__ T*)input, totalElements);
59	        countWsGm_.SetGlobalBuffer((__gm__ int64_t*)countWs, formerNum_ + 1);
60	
61	        pipe_.InitBuffer(inQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
62	        pipe_.InitBuffer(countOutBuf_, sizeof(int64_t));
63	    }
64	
65	    __aicore__ inline void Process()
66	    {
67	        int64_t blockIdx = GetBlockIdx();
68	        int64_t coreLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
69	        if (coreLength <= 0) {
70	            WriteCount(blockIdx, 0);
71	            return;
72	        }
73	
74	        int64_t coreOffset = (blockIdx < formerNum_)
75	            ? blockIdx * formerLength_
76	            : formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;
77	
78	        int64_t tileNum = (coreLength + tileLength_ - 1) / tileLength_;
79	        int64_t tailTileLength = coreLength - (tileNum - 1) * tileLength_;
80	        int64_t localCount = 0;
81	
82	        for (int64_t i = 0; i < tileNum - 1; i++) {
83	            localCount += ProcessTile(coreOffset + i * tileLength_, tileLength_);
84	        }
85	        localCount += ProcessTile(coreOffset + (tileNum - 1) * tileLength_, tailTileLength);
86	
87	        WriteCount(blockIdx, localCount);
88	    }
89	
90	private:
91	    __aicore__ inline void WriteCount(int64_t idx, int64_t count)
92	    {
93	        LocalTensor<int64_t> cntLocal = countOutBuf_.Get<int64_t>();
94	        cntLocal.SetValue(0, count);
95	
96	        DataCopyExtParams copyParams;
97	        copyParams.blockCount = 1;
98	        copyParams.blockLen = static_cast<uint32_t>(sizeof(int64_t));
99	        copyParams.srcStride = 0;
100	        copyParams.dstStride = 0;
101	        DataCopyPad(countWsGm_[idx], cntLocal, copyParams);
102	    }
103	
104	    __aicore__ inline int64_t ProcessTile(int64_t gmOffset, int64_t curTileLength)
105	    {
106	        if (curTileLength <= 0) return 0;
107	
108	        LocalTensor<T> xLocal = inQueue_.AllocTensor<T>();
109	
110	        DataCopyExtParams copyParams;
111	        copyParams.blockCount = 1;
112	        copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
113	        copyParams.srcStride = 0;
114	        copyParams.dstStride = 0;
115	
116	        DataCopyPadExtParams<T> padParams;
117	        padParams.isPad = false;
118	
119	        DataCopyPad(xLocal, inputGm_[gmOffset], copyParams, padParams);
120	        PipeBarrier<PIPE_ALL>();
121	
122	        int64_t count = 0;
123	        for (int64_t i = 0; i < curTileLength; i++) {
124	            if (IsNonZero(xLocal.GetValue(i))) {
125	                count++;
126	            }
127	        }
128	
129	        inQueue_.FreeTensor(xLocal);
130	        return count;
131	    }
132	
133	private:
134	    TPipe pipe_;
135	    TQue<TPosition::VECIN, BUFFER_NUM> inQueue_;
136	    TBuf<TPosition::VECCALC> countOutBuf_;
137	    GlobalTensor<T> inputGm_;
138	    GlobalTensor<int64_t> countWsGm_;
139	    int64_t totalElements_ = 0;
140	    int64_t formerNum_ = 0;
141	    int64_t formerLength_ = 0;
142	    int64_t tailLength_ = 0;
143	    int64_t tileLength_ = 0;
144	};
145	
146	
147	extern "C" __global__ __aicore__ void nonzero_count(
148	    GM_ADDR input, GM_ADDR countWs,
149	    int64_t totalElements, int64_t formerNum, int64_t formerLength,
150	    int64_t tailLength, int64_t tileLength, int64_t dtypeSize)
151	{
152	    if (totalElements <= 0) return;
153	
154	    if (dtypeSize == 4) {
155	        NonzeroCountKernel<float> op;
156	        op.Init(input, countWs, totalElements, formerNum, formerLength,
157	                tailLength, tileLength, dtypeSize);
158	        op.Process();
159	    } else if (dtypeSize == 2) {
160	        NonzeroCountKernel<half> op;
161	        op.Init(input, countWs, totalElements, formerNum, formerLength,
162	                tailLength, tileLength, dtypeSize);
163	        op.Process();
164	    } else if (dtypeSize == 8) {
165	        NonzeroCountKernel<int64_t> op;
166	        op.Init(input, countWs, totalElements, formerNum, formerLength,
167	                tailLength, tileLength, dtypeSize);
168	        op.Process();
169	    }
170	}
171	
172	
173	// =========================== Output Kernel ============================
174	
175	template <typename T>
176	class NonzeroOutputKernel {
177	public:
178	    __aicore__ inline NonzeroOutputKernel() {}
179	
180	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR offsetWs,
181	                                 int64_t totalElements, int64_t /*ndim*/,
182	                                 int64_t formerNum, int64_t formerLength,
183	                                 int64_t tailLength, int64_t tileLength,
184	                                 int64_t /*dtypeSize*/)
185	    {
186	        totalElements_ = totalElements;
187	        formerNum_ = formerNum;
188	        formerLength_ = formerLength;
189	        tailLength_ = tailLength;
190	        tileLength_ = tileLength;
191	
192	        inputGm_.SetGlobalBuffer((__gm__ T*)input, totalElements);
193	        outputGm_.SetGlobalBuffer((__gm__ int64_t*)output, totalElements);
194	        offsetWsGm_.SetGlobalBuffer((__gm__ int64_t*)offsetWs, formerNum_ + 1);
195	
196	        pipe_.InitBuffer(inQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
197	        pipe_.InitBuffer(coordBuf_, sizeof(int64_t));
198	        pipe_.InitBuffer(offsetBuf_, sizeof(int64_t));
199	    }
200	
201	    __aicore__ inline void Process()
202	    {
203	        int64_t blockIdx = GetBlockIdx();
204	        int64_t coreLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
205	        if (coreLength <= 0) return;
206	
207	        int64_t coreOffset = (blockIdx < formerNum_)
208	            ? blockIdx * formerLength_
209	            : formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;
210	
211	        int64_t outBase = ReadOffset(blockIdx);
212	
213	        int64_t tileNum = (coreLength + tileLength_ - 1) / tileLength_;
214	        int64_t tailTileLength = coreLength - (tileNum - 1) * tileLength_;
215	        int64_t localIdx = 0;
216	
217	        for (int64_t i = 0; i < tileNum - 1; i++) {
218	            localIdx = ProcessOutputTile(coreOffset + i * tileLength_,
219	                                          tileLength_, outBase, localIdx);
220	        }
221	        localIdx = ProcessOutputTile(coreOffset + (tileNum - 1) * tileLength_,
222	                                      tailTileLength, outBase, localIdx);
223	    }
224	
225	private:
226	    __aicore__ inline int64_t ReadOffset(int64_t idx)
227	    {
228	        LocalTensor<int64_t> offLocal = offsetBuf_.Get<int64_t>();
229	
230	        DataCopyExtParams copyParams;
231	        copyParams.blockCount = 1;
232	        copyParams.blockLen = static_cast<uint32_t>(sizeof(int64_t));
233	        copyParams.srcStride = 0;
234	        copyParams.dstStride = 0;
235	
236	        DataCopyPadExtParams<int64_t> padParams;
237	        padParams.isPad = false;
238	
239	        DataCopyPad(offLocal, offsetWsGm_[idx], copyParams, padParams);
240	        PipeBarrier<PIPE_ALL>();
241	
242	        return offLocal.GetValue(0);
243	    }
244	
245	    __aicore__ inline int64_t ProcessOutputTile(int64_t gmOffset,
246	                                                  int64_t curTileLength,
247	                                                  int64_t outBase,
248	                                                  int64_t localIdx)
249	    {
250	        if (curTileLength <= 0) return localIdx;
251	
252	        LocalTensor<T> xLocal = inQueue_.AllocTensor<T>();
253	
254	        DataCopyExtParams copyParams;
255	        copyParams.blockCount = 1;
256	        copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
257	        copyParams.srcStride = 0;
258	        copyParams.dstStride = 0;
259	
260	        DataCopyPadExtParams<T> padParams;
261	        padParams.isPad = false;
262	
263	        DataCopyPad(xLocal, inputGm_[gmOffset], copyParams, padParams);
264	        PipeBarrier<PIPE_ALL>();
265	
266	        LocalTensor<int64_t> coordLocal = coordBuf_.Get<int64_t>();
267	
268	        for (int64_t i = 0; i < curTileLength; i++) {
269	            if (IsNonZero(xLocal.GetValue(i))) {
270	                int64_t flatIdx = gmOffset + i;
271	
272	                // 输出 flatIdx（Host 端转换为多维坐标）
273	                coordLocal.SetValue(0, flatIdx);
274	
275	                int64_t outOffset = outBase + localIdx;
276	                DataCopyExtParams outParams;
277	                outParams.blockCount = 1;
278	                outParams.blockLen = static_cast<uint32_t>(sizeof(int64_t));
279	                outParams.srcStride = 0;
280	                outParams.dstStride = 0;
281	                DataCopyPad(outputGm_[outOffset], coordLocal, outParams);
282	
283	                localIdx++;
284	            }
285	        }
286	
287	        inQueue_.FreeTensor(xLocal);
288	        return localIdx;
289	    }
290	
291	private:
292	    TPipe pipe_;
293	    TQue<TPosition::VECIN, BUFFER_NUM> inQueue_;
294	    TBuf<TPosition::VECCALC> coordBuf_;
295	    TBuf<TPosition::VECCALC> offsetBuf_;
296	    GlobalTensor<T> inputGm_;
297	    GlobalTensor<int64_t> outputGm_;
298	    GlobalTensor<int64_t> offsetWsGm_;
299	    int64_t totalElements_ = 0;
300	    int64_t formerNum_ = 0;
301	    int64_t formerLength_ = 0;
302	    int64_t tailLength_ = 0;
303	    int64_t tileLength_ = 0;
304	};
305	
306	
307	extern "C" __global__ __aicore__ void nonzero_output(
308	    GM_ADDR input, GM_ADDR output, GM_ADDR offsetWs,
309	    int64_t totalElements, int64_t ndim,
310	    int64_t formerNum, int64_t formerLength, int64_t tailLength,
311	    int64_t tileLength, int64_t dtypeSize)
312	{
313	    if (totalElements <= 0) return;
314	
315	    if (dtypeSize == 4) {
316	        NonzeroOutputKernel<float> op;
317	        op.Init(input, output, offsetWs, totalElements, ndim,
318	                formerNum, formerLength, tailLength, tileLength, dtypeSize);
319	        op.Process();
320	    } else if (dtypeSize == 2) {
321	        NonzeroOutputKernel<half> op;
322	        op.Init(input, output, offsetWs, totalElements, ndim,
323	                formerNum, formerLength, tailLength, tileLength, dtypeSize);
324	        op.Process();
325	    } else if (dtypeSize == 8) {
326	        NonzeroOutputKernel<int64_t> op;
327	        op.Init(input, output, offsetWs, totalElements, ndim,
328	                formerNum, formerLength, tailLength, tileLength, dtypeSize);
329	        op.Process();
330	    }
331	}
