// ============================================================
// Nonzero 算子 Kernel 实现
// 两阶段设计:
//   Pass 1 (nonzero_count): 各核统计非零元素数量，写入 workspace
//   Pass 2 (nonzero_output): 各核输出非零元素的 flatIdx
//   Host 端将 flatIdx 转换为多维坐标
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;
constexpr int64_t MAX_NDIM = 8;


// =========================== 辅助: 零值检查 ============================

template <typename T>
__aicore__ inline bool IsNonZero(T val)
{
    if constexpr (sizeof(T) == 2) {
        return (float)val != 0.0f;
    } else {
        return val != static_cast<T>(0);
    }
}


// =========================== Count Kernel ============================

template <typename T>
class NonzeroCountKernel {
public:
    __aicore__ inline NonzeroCountKernel() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR countWs,
                                 int64_t totalElements, int64_t formerNum,
                                 int64_t formerLength, int64_t tailLength,
                                 int64_t tileLength, int64_t /*dtypeSize*/)
    {
        totalElements_ = totalElements;
        formerNum_ = formerNum;
        formerLength_ = formerLength;
        tailLength_ = tailLength;
        tileLength_ = tileLength;

        inputGm_.SetGlobalBuffer((__gm__ T*)input, totalElements);
        countWsGm_.SetGlobalBuffer((__gm__ int64_t*)countWs, formerNum_ + 1);

        pipe_.InitBuffer(inQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
        pipe_.InitBuffer(countOutBuf_, sizeof(int64_t));
    }

    __aicore__ inline void Process()
    {
        int64_t blockIdx = GetBlockIdx();
        int64_t coreLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
        if (coreLength <= 0) {
            WriteCount(blockIdx, 0);
            return;
        }

        int64_t coreOffset = (blockIdx < formerNum_)
            ? blockIdx * formerLength_
            : formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;

        int64_t tileNum = (coreLength + tileLength_ - 1) / tileLength_;
        int64_t tailTileLength = coreLength - (tileNum - 1) * tileLength_;
        int64_t localCount = 0;

        for (int64_t i = 0; i < tileNum - 1; i++) {
            localCount += ProcessTile(coreOffset + i * tileLength_, tileLength_);
        }
        localCount += ProcessTile(coreOffset + (tileNum - 1) * tileLength_, tailTileLength);

        WriteCount(blockIdx, localCount);
    }

private:
    __aicore__ inline void WriteCount(int64_t idx, int64_t count)
    {
        LocalTensor<int64_t> cntLocal = countOutBuf_.Get<int64_t>();
        cntLocal.SetValue(0, count);

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(sizeof(int64_t));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPad(countWsGm_[idx], cntLocal, copyParams);
    }

    __aicore__ inline int64_t ProcessTile(int64_t gmOffset, int64_t curTileLength)
    {
        if (curTileLength <= 0) return 0;

        LocalTensor<T> xLocal = inQueue_.AllocTensor<T>();

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;

        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;

        DataCopyPad(xLocal, inputGm_[gmOffset], copyParams, padParams);
        PipeBarrier<PIPE_ALL>();

        int64_t count = 0;
        for (int64_t i = 0; i < curTileLength; i++) {
            if (IsNonZero(xLocal.GetValue(i))) {
                count++;
            }
        }

        inQueue_.FreeTensor(xLocal);
        return count;
    }

private:
    TPipe pipe_;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue_;
    TBuf<TPosition::VECCALC> countOutBuf_;
    GlobalTensor<T> inputGm_;
    GlobalTensor<int64_t> countWsGm_;
    int64_t totalElements_ = 0;
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailLength_ = 0;
    int64_t tileLength_ = 0;
};


extern "C" __global__ __aicore__ void nonzero_count(
    GM_ADDR input, GM_ADDR countWs,
    int64_t totalElements, int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength, int64_t dtypeSize)
{
    if (totalElements <= 0) return;

    if (dtypeSize == 4) {
        NonzeroCountKernel<float> op;
        op.Init(input, countWs, totalElements, formerNum, formerLength,
                tailLength, tileLength, dtypeSize);
        op.Process();
    } else if (dtypeSize == 2) {
        NonzeroCountKernel<half> op;
        op.Init(input, countWs, totalElements, formerNum, formerLength,
                tailLength, tileLength, dtypeSize);
        op.Process();
    } else if (dtypeSize == 8) {
        NonzeroCountKernel<int64_t> op;
        op.Init(input, countWs, totalElements, formerNum, formerLength,
                tailLength, tileLength, dtypeSize);
        op.Process();
    }
}


// =========================== Output Kernel ============================

template <typename T>
class NonzeroOutputKernel {
public:
    __aicore__ inline NonzeroOutputKernel() {}

    __aicore__ inline void Init(GM_ADDR input, GM_ADDR output, GM_ADDR offsetWs,
                                 int64_t totalElements, int64_t /*ndim*/,
                                 int64_t formerNum, int64_t formerLength,
                                 int64_t tailLength, int64_t tileLength,
                                 int64_t /*dtypeSize*/)
    {
        totalElements_ = totalElements;
        formerNum_ = formerNum;
        formerLength_ = formerLength;
        tailLength_ = tailLength;
        tileLength_ = tileLength;

        inputGm_.SetGlobalBuffer((__gm__ T*)input, totalElements);
        outputGm_.SetGlobalBuffer((__gm__ int64_t*)output, totalElements);
        offsetWsGm_.SetGlobalBuffer((__gm__ int64_t*)offsetWs, formerNum_ + 1);

        pipe_.InitBuffer(inQueue_, BUFFER_NUM, tileLength_ * sizeof(T));
        pipe_.InitBuffer(coordBuf_, sizeof(int64_t));
        pipe_.InitBuffer(offsetBuf_, sizeof(int64_t));
    }

    __aicore__ inline void Process()
    {
        int64_t blockIdx = GetBlockIdx();
        int64_t coreLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
        if (coreLength <= 0) return;

        int64_t coreOffset = (blockIdx < formerNum_)
            ? blockIdx * formerLength_
            : formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;

        int64_t outBase = ReadOffset(blockIdx);

        int64_t tileNum = (coreLength + tileLength_ - 1) / tileLength_;
        int64_t tailTileLength = coreLength - (tileNum - 1) * tileLength_;
        int64_t localIdx = 0;

        for (int64_t i = 0; i < tileNum - 1; i++) {
            localIdx = ProcessOutputTile(coreOffset + i * tileLength_,
                                          tileLength_, outBase, localIdx);
        }
        localIdx = ProcessOutputTile(coreOffset + (tileNum - 1) * tileLength_,
                                      tailTileLength, outBase, localIdx);
    }

private:
    __aicore__ inline int64_t ReadOffset(int64_t idx)
    {
        LocalTensor<int64_t> offLocal = offsetBuf_.Get<int64_t>();

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(sizeof(int64_t));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;

        DataCopyPadExtParams<int64_t> padParams;
        padParams.isPad = false;

        DataCopyPad(offLocal, offsetWsGm_[idx], copyParams, padParams);
        PipeBarrier<PIPE_ALL>();

        return offLocal.GetValue(0);
    }

    __aicore__ inline int64_t ProcessOutputTile(int64_t gmOffset,
                                                  int64_t curTileLength,
                                                  int64_t outBase,
                                                  int64_t localIdx)
    {
        if (curTileLength <= 0) return localIdx;

        LocalTensor<T> xLocal = inQueue_.AllocTensor<T>();

        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;

        DataCopyPadExtParams<T> padParams;
        padParams.isPad = false;

        DataCopyPad(xLocal, inputGm_[gmOffset], copyParams, padParams);
        PipeBarrier<PIPE_ALL>();

        LocalTensor<int64_t> coordLocal = coordBuf_.Get<int64_t>();

        for (int64_t i = 0; i < curTileLength; i++) {
            if (IsNonZero(xLocal.GetValue(i))) {
                int64_t flatIdx = gmOffset + i;

                // 输出 flatIdx（Host 端转换为多维坐标）
                coordLocal.SetValue(0, flatIdx);

                int64_t outOffset = outBase + localIdx;
                DataCopyExtParams outParams;
                outParams.blockCount = 1;
                outParams.blockLen = static_cast<uint32_t>(sizeof(int64_t));
                outParams.srcStride = 0;
                outParams.dstStride = 0;
                DataCopyPad(outputGm_[outOffset], coordLocal, outParams);

                localIdx++;
            }
        }

        inQueue_.FreeTensor(xLocal);
        return localIdx;
    }

private:
    TPipe pipe_;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue_;
