// ============================================================
// Nonzero 算子 Host 端实现
// 两阶段设计:
//   Pass 1 (nonzero_count): 各核统计非零元素数量
//   Pass 2 (nonzero_output): 各核输出 flatIdx
//   Host 端将 flatIdx 转换为多维坐标
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_nonzero_count.h"
#include "aclrtlaunch_nonzero_output.h"

#include <torch/extension.h>
#include <vector>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTES = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;
constexpr int64_t MAX_NDIM = 8;

static std::vector<at::Tensor> nonzero_impl(
    const at::Tensor &x,
    int64_t as_tuple)
{
    // ---- 输入校验 ----
    TORCH_CHECK(x.device().type() == at::DeviceType::PrivateUse1,
                "nonzero: input must be on NPU device");
    TORCH_CHECK(x.is_contiguous(),
                "nonzero: input must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16 ||
                x.scalar_type() == at::kInt ||
                x.scalar_type() == at::kLong,
                "nonzero: unsupported dtype");

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t totalElements = x.numel();
    int64_t ndim = x.dim();
    int64_t dtypeSize = x.element_size();

    if (totalElements == 0) {
        auto emptyOut = at::empty({0, ndim},
                                   at::TensorOptions().dtype(at::kLong).device(x.device()));
        if (as_tuple) {
            std::vector<at::Tensor> parts;
            for (int64_t d = 0; d < ndim; d++) {
                parts.push_back(at::empty({0},
                    at::TensorOptions().dtype(at::kLong).device(x.device())));
            }
            return parts;
        }
        return {emptyOut};
    }

    // ---- Block 级 Tiling ----
    int64_t alignElementsCore = std::max(int64_t(1), CACHE_LINE_BYTES / dtypeSize);
    int64_t totalLengthCore = (totalElements + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign =
        ((totalLengthCore + alignElementsCore - 1) / alignElementsCore) * alignElementsCore;
    int64_t usedCoreNum = (totalElements + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum < 1) usedCoreNum = 1;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;

    int64_t formerNum = std::max(int64_t(0), usedCoreNum - 1);
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = std::max(int64_t(0), totalElements - formerNum * formerLength);

    // ---- UB 级 tileLength ----
    constexpr int64_t extraBufBytes = 256;
    int64_t bufferCoefficient = dtypeSize * 2;
    int64_t availableUB = static_cast<int64_t>(ubSize) - extraBufBytes;
    if (availableUB < bufferCoefficient) availableUB = bufferCoefficient;
    int64_t maxTileElements = availableUB / bufferCoefficient;
    int64_t alignElementsUb = std::max(int64_t(1), UB_ALIGN_BYTES / dtypeSize);
    int64_t tileLength = (maxTileElements / alignElementsUb) * alignElementsUb;
    if (tileLength < alignElementsUb) tileLength = alignElementsUb;

    // ---- workspace ----
    auto workspaceOpts = at::TensorOptions().dtype(at::kLong).device(x.device());
    auto workspace = at::zeros({coreNum * 2}, workspaceOpts);

    // ---- Pass 1: Count ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int64_t totalElementsVal = totalElements;
    int64_t formerNumVal = formerNum;
    int64_t formerLengthVal = formerLength;
    int64_t tailLengthVal = tailLength;
    int64_t tileLengthVal = tileLength;

    EXEC_KERNEL_CMD(nonzero_count, blockDim,
                    x, workspace, totalElementsVal, formerNumVal,
                    formerLengthVal, tailLengthVal, tileLengthVal, dtypeSize);

    // ---- 读取 per-core counts ----
    auto cpuWs = workspace.to(at::kCPU);
    const int64_t *wsData = cpuWs.data_ptr<int64_t>();

    std::vector<int64_t> perCoreOffsets(usedCoreNum + 1, 0);
    int64_t totalNonzero = 0;
    for (int64_t c = 0; c < usedCoreNum; c++) {
        perCoreOffsets[c] = totalNonzero;
        totalNonzero += wsData[c];
    }
    perCoreOffsets[usedCoreNum] = totalNonzero;

    if (totalNonzero == 0) {
        auto emptyOut = at::empty({0, ndim},
                                   at::TensorOptions().dtype(at::kLong).device(x.device()));
        if (as_tuple) {
            std::vector<at::Tensor> parts;
            for (int64_t d = 0; d < ndim; d++) {
                parts.push_back(at::empty({0},
                    at::TensorOptions().dtype(at::kLong).device(x.device())));
            }
            return parts;
        }
        return {emptyOut};
    }

    // ---- 写入 per-core offsets ----
    auto offsetTensor = at::empty({usedCoreNum},
                                   at::TensorOptions().dtype(at::kLong).device(x.device()));
    auto offsetCpu = at::empty({usedCoreNum}, at::TensorOptions().dtype(at::kLong));
    int64_t *offsetsData = offsetCpu.data_ptr<int64_t>();
    for (int64_t c = 0; c < usedCoreNum; c++) {
        offsetsData[c] = perCoreOffsets[c];
    }
    offsetTensor.copy_(offsetCpu.to(x.device()));

    // ---- kernel 输出: 1D flatIdx tensor ----
    auto flatIdxTensor = at::empty({totalNonzero},
                                    at::TensorOptions().dtype(at::kLong).device(x.device()));
    int64_t ndimVal = ndim;

    // ---- Pass 2: Output flatIdx ----
    EXEC_KERNEL_CMD(nonzero_output, blockDim,
                    x, flatIdxTensor, offsetTensor,
                    totalElementsVal, ndimVal,
                    formerNumVal, formerLengthVal, tailLengthVal,
                    tileLengthVal, dtypeSize);

    // ---- Host 端: flatIdx → 多维坐标 ----
    auto flatIdxCpu = flatIdxTensor.to(at::kCPU);
    const int64_t *flatData = flatIdxCpu.data_ptr<int64_t>();

    // 计算 C-order strides
    int64_t strides[MAX_NDIM] = {0};
    if (ndim > 0) {
        strides[ndim - 1] = 1;
        for (int64_t d = ndim - 2; d >= 0; d--) {
            strides[d] = strides[d + 1] * x.size(d + 1);
        }
    }

    auto outputCpu = at::empty({totalNonzero, ndim}, at::TensorOptions().dtype(at::kLong));
    int64_t *outputData = outputCpu.data_ptr<int64_t>();
    for (int64_t k = 0; k < totalNonzero; k++) {
        int64_t flatIdx = flatData[k];
        int64_t remaining = flatIdx;
        for (int64_t d = 0; d < ndim; d++) {
            int64_t stride = strides[d];
            int64_t coord;
            if (stride > 0) {
                coord = remaining / stride;
                remaining = remaining % stride;
            } else {
                coord = remaining;
                remaining = 0;
            }
            outputData[k * ndim + d] = coord;
        }
    }

    auto output = outputCpu.to(x.device());

    if (as_tuple) {
        std::vector<at::Tensor> parts;
        for (int64_t d = 0; d < ndim; d++) {
            parts.push_back(output.select(1, d).clone());
        }
        return parts;
    }

    return {output};
}

// =========================== 公开接口 ============================

at::Tensor nonzero(const at::Tensor &x, int64_t as_tuple)
{
    auto result = nonzero_impl(x, as_tuple);
    return result[0];
}

std::vector<at::Tensor> nonzero_as_tuple(const at::Tensor &x)
{
    return nonzero_impl(x, 1);
}

}  // namespace ascend_kernel
