from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "nonzero_ext*")

# 优先 whl import（触发 TORCH_LIBRARY 注册）
try:
    import nonzero_ext  # noqa: F401
except ImportError:
    # 兜底：直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    """
    Nonzero AscendC 实现.
    内部调用 torch.ops.npu.nonzero / torch.ops.npu.nonzero_tuple.
    """

    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor, as_tuple: bool = False):
        """
        Args:
            x (torch.Tensor): Input tensor.
            as_tuple (bool): If True, returns a tuple of 1-D tensors.
        Returns:
            torch.Tensor or tuple: Indices of non-zero elements.
        """
        if as_tuple:
            result = torch.ops.npu.nonzero_tuple(x)
            return tuple(result)
        else:
            return torch.ops.npu.nonzero(x, 0)
